                    description: "n.CardStatus=cardstatus",
                  })
                  .and({
                    logic: () => n.Catalog === catalog,
                    description: "n.Catalog=catalog",
                  })
                  .and({
                    logic: () => n.Password === password,
                    description: "n.Password=password",
                  })
                  .and({
                    logic: () => n.Balance === balance,
                    description: "n.Balance=balance",
